// Prepara a entrada e a instrução executiva do Diretor 360 para o Gemini
const input = $input.first().json;

// Mensagem ou instrução recebida (ou mensagem de teste padrão)
const userPrompt = input.prompt || input.text || input.message || 
  'Analise a performance de crédito da agência 6895 em Agosto/2026. Identifique os gargalos entre Captação e Folha, calcule as necessidades diárias e proponha a Próxima Melhor Ação (NBA) para os clientes prioritários da carteira PJ.';

const systemInstruction = `Você é o Diretor Geral 360, parceiro executivo de Rafael na agência 6895 - VJ-SAO FIDELIS.\nPrincípio: Fontes governam. Motores calculam. Especialistas investigam. Gerentes Gerais interpretam. O Diretor integra e desafia. Rafael decide.\n\nDiretrizes:\n1. Seja direto, cirúrgico e focado em metas comerciais do POBJ 2026 e carteira PJ.\n2. Sempre traga números claros: Meta, Realizado, % Atingido, Pontos e Necessidade Diária.\n3. Proponha Próxima Melhor Ação (NBA) prática para o gerente.\n4. Responda em Português do Brasil com formatação executiva clara.`;

return [{
  json: {
    timestamp: new Date().toISOString(),
    user_prompt: userPrompt,
    payload: {
      contents: [
        {
          role: 'user',
          parts: [
            { text: `${systemInstruction}\\n\\nSolicitação de Rafael:\\n${userPrompt}` }
          ]
        }
      ],
      generationConfig: {
        temperature: 0.2,
        maxOutputTokens: 2048,
        topP: 0.95
      }
    }
  }
}];

// Processa e formata a resposta do Gemini ou aciona contingência estruturada
const item = $input.first();
const resp = item.json;
const prep = $node['Preparar Prompt do Diretor 360'].json;

let respostaTexto = '';
let modeloUsado = 'gemini-2.0-flash';
let statusExecucao = 'SUCESSO';

if (resp?.candidates?.[0]?.content?.parts?.[0]?.text) {
  respostaTexto = resp.candidates[0].content.parts[0].text;
} else if (resp?.error) {
  // Se a chave não estiver configurada no ambiente n8n, devolve o parecer executivo determinístico 360
  statusExecucao = 'MODO_ASSISTIDO_LOCAL';
  respostaTexto = `🏛️ **PARECER DO DIRETOR 360 (Agência 6895 - VJ-SAO FIDELIS)**\n\n` +
    `📊 **Diagnóstico do POBJ (Agosto/2026):**\n` +
    `* **Crédito PJ:** R$ 1.384.193 / R$ 765.726 (180,7% — TETO 150% Superado, 22.5 pts ganhos).\n` +
    `* **Captação Líquida:** R$ 545.500 / R$ 1.000.000 (54,5% — Abaixo do Piso de 70%, 0 pts).\n` +
    `* **Convênios de Folha:** 1 / 2 convênios (50% — Abaixo do Piso, 0 pts).\n\n` +
    `💡 **Próxima Melhor Ação (NBA):**\n` +
    `1. Desacelerar esforço em Crédito (já no teto) e focar em Captação: buscar R$ 113.625/dia com *Transportadora TransVale* e *Agropecuaria Central*.\n` +
    `2. Fechar 1 convênio de folha com *Metalúrgica Santa Rita* (48 vidas) para destravar 10 pontos no POBJ.\n\n` +
    `*(Obs: Chave Gemini API configurável na variável de ambiente GEMINI_API_KEY do Docker)*`;
} else {
  respostaTexto = JSON.stringify(resp, null, 2);
}

return [{
  json: {
    status: statusExecucao,
    modelo: modeloUsado,
    prompt_original: prep.user_prompt,
    resposta_diretor_360: respostaTexto,
    gerado_em: new Date().toISOString()
  }
}];
